// HasApprover applies the HasEdge predicate on the "approver" edge.
func HasApprover() predicate.RoutingExperiment {
	return predicate.RoutingExperiment(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ApproverTable, ApproverColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasApproverWith applies the HasEdge predicate on the "approver" edge with a given conditions (other predicates).
func HasApproverWith(preds ...predicate.User) predicate.RoutingExperiment {
	return predicate.RoutingExperiment(func(s *sql.Selector) {
		step := newApproverStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RoutingExperiment) predicate.RoutingExperiment {
	return predicate.RoutingExperiment(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RoutingExperiment) predicate.RoutingExperiment {
	return predicate.RoutingExperiment(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RoutingExperiment) predicate.RoutingExperiment {
	return predicate.RoutingExperiment(sql.NotPredicates(p))
}
